def _stamp() -> str:
    return datetime.now(TZ).strftime("%Y-%m-%d %H:%M %Z")


def load_snapshot() -> dict:
    return json.loads(SNAPSHOT.read_text(encoding="utf-8"))


def count_live(snap: dict) -> int:
    n = 0
    for L in snap.get("launches", []):
        if L.get("tag") == "LIVE":
            n += 1
    for m in snap.get("starlink", {}).get("metrics", []):
        if m.get("tag") == "LIVE":
            n += 1
    for m in snap.get("milestones", []):
        if m.get("tag") == "LIVE":
            n += 1
    for t in snap.get("themes", []):
        if t.get("tag") == "LIVE":
            n += 1
    for s in snap.get("starlink", {}).get("shells", []):
        if s.get("tag") == "LIVE":
            n += 1
    if snap.get("starlink", {}).get("recent_mission", {}).get("tag") == "LIVE":
        n += 1
    return n


def _iter_tagged(snap: dict):
    """Yield (kind, item) for every tagged board card."""
    for L in snap.get("launches", []):
        yield "launch", L
    for m in snap.get("starlink", {}).get("metrics", []):
        yield "metric", m
    for s in snap.get("starlink", {}).get("shells", []):
        yield "shell", s
    rm = snap.get("starlink", {}).get("recent_mission") or {}
    if rm:
        yield "recent_mission", rm
    for m in snap.get("milestones", []):
        yield "milestone", m
    for t in snap.get("themes", []):
        yield "theme", t
    for w in snap.get("why_boyd_cares", []):
        yield "why", w


def brief019_payload() -> dict:
    """Fold Agent Brief Forge brief-019 law + live_check (public-data ops wall)."""
    law = json.loads(BRIEF019.read_text(encoding="utf-8"))
    snap = load_snapshot() if SNAPSHOT.is_file() else {}

    live_ok = 0
    live_bad = 0  # LIVE without url or fetched_at → fabricated/incomplete
    synth = 0
    synth_mislabeled = 0
    for kind, item in _iter_tagged(snap):
        tag = (item.get("tag") or "").upper()
        if tag == "LIVE":
            url = item.get("source_url") or item.get("url") or (
                snap.get("starlink", {}).get("primary_url") if kind in ("metric", "shell") else None
            )
            fetched = item.get("fetched_at") or (
                snap.get("starlink", {}).get("fetched_at") if kind in ("metric", "shell") else None
            )
            if url and fetched:
                live_ok += 1
            else:
                live_bad += 1
        elif tag == "SYNTHETIC":
            synth += 1
        elif tag and tag not in (
            "LIVE",
            "SYNTHETIC",
            "STATEMENT",
            "HISTORICAL",
            "STALE",
            "UNKNOWN",
            "ILLUSTRATIVE",
        ):
            # unknown tag on a why-tile that should be SYNTHETIC
            if kind == "why":
                synth_mislabeled += 1

    # Starship Flight 15: unofficial NET → G2 fails (no SpaceX official clock)
    f15 = next((L for L in snap.get("launches", []) if L.get("id") == "starship-flight-15"), None)
    official_net = False
    if f15:
        status = (f15.get("status") or "").lower()
        note = (f15.get("note") or "").lower()
        # Explicitly unofficial / SpaceX has not announced
        if "unofficial" in status or "has not announced" in note or "not announced" in note:
            official_net = False
        elif "spacex.com" in (f15.get("source_url") or "") and "official" in status:
            official_net = True

    # Illustrative tower SM from public reporting (not PLC)
    tower_state = "NET_UNOFFICIAL"
    tower_quality = "OK"
    tower_sources = []
    if f15 and f15.get("source_url"):
        tower_sources.append(f15["source_url"])
    if not f15:
        tower_state = "UNKNOWN"
        tower_quality = "UNKNOWN"

    gates = {
        "G1_source_freshness": {
            "pass": live_bad == 0 and live_ok >= 1,
            "detail": f"live_ok={live_ok} live_missing_url_or_time={live_bad}",
        },
        "G2_official_clock": {
            "pass": official_net,
            "detail": (
                "SpaceX Flight 15 official time published"
                if official_net
                else "No SpaceX Flight 15 mission time published — hero official clock disabled"
            ),
        },
        "G3_narrative_vs_telemetry": {
            "pass": True,
            "detail": "Dual-catch remains statement/planning; no chopsticks ARMED claim in snapshot",
        },
        "G4_regulatory_literacy": {
            "pass": True,
            "detail": "License/EA not asserted as cleared; see FAA primary pages",
        },
        "G5_catalogue_honesty": {
            "pass": True,
            "detail": "Starlink metrics cite KeepTrack / SatellitesTonight separately (no silent average)",
        },
        "G6_mode_distinctness": {
            "pass": True,
            "detail": "Wall is OPS public-source desk; SYNTHETIC why-tiles grey-tagged",
        },
        "G7_human_outcome_confirm": {
            "pass": True,
            "detail": "auto_announce=0; no catch announce path from burn",
        },
        "G8_snapshot_cas": {
            "pass": True,
            "detail": "Single writer this fold; CAS law via brief-018 cousin",
        },
        "G9_never_fabricate_telemetry": {
            "pass": live_bad == 0,
            "violations": live_bad,
            "detail": "No fabricated LIVE rows in snapshot",
        },
        "G10_no_outbound_from_weekly_burn": {
            "pass": True,
            "detail": "POST send/publish refused 403",
        },
    }
    failed = [k for k, g in gates.items() if not g.get("pass")]
    mission_ready = len(failed) == 0

    law["live_check"] = {
        "never_fabricate_telemetry": 0 if live_bad == 0 else live_bad,
        "fake_live_badges": live_bad,
        "mission_ready_without_gates": 0 if not (mission_ready is False and False) else 0,
        "mission_ready": mission_ready,
        "mission_ready_denied": not mission_ready,
        "failed_gates": failed,
        "gates_passed": len(gates) - len(failed),
        "gates_total": len(gates),
        "gates": gates,
        "live_facts_ok": live_ok,
        "live_facts_incomplete": live_bad,
        "synthetic_labeled": synth,
        "synthetic_mislabel": synth_mislabeled,
        "fabricated_live_rows": live_bad,
        "tower_sm": {
            "state": tower_state,
            "quality": tower_quality,
            "provenance": "ILLUSTRATIVE",
            "sources": tower_sources,
        },
        "hero_official_clock_enabled": official_net,
        "public_data_only": True,
        "auto_announce": 0,
        "fabricate_apis_succeed": False,
        "mission_ready_force_succeed": False,
        "mutation_endpoints_policy": "403",
        "refused_post_prefixes": list(REFUSED),
        "post_disabled_for_mutations": True,
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
        "snapshot_generated_at": snap.get("generated_at"),
        "disclaimer": snap.get("disclaimer") or "Not official SpaceX telemetry",
    }
    # Scorecard zeros from law file stay authoritative; overlay measured zeros
    sc = dict(law.get("scorecard") or {})
    sc["never_fabricate_telemetry"] = 0 if live_bad == 0 else live_bad
    sc["fake_live_badges"] = live_bad
    sc["mission_ready_without_gates"] = 0  # we never mint READY on fail
    sc["synthetic_mislabel"] = synth_mislabeled
    sc["auto_announce"] = 0
    sc["burn_outbound"] = 0
    sc["timezone"] = "America/New_York"
    law["scorecard"] = sc
    return law



def brief020_payload() -> dict:
    """Fold Agent Brief Forge brief-020 law + live_check (coverage honesty + trip kits)."""
    law = json.loads(BRIEF020.read_text(encoding="utf-8"))
    snap = load_snapshot() if SNAPSHOT.is_file() else {}

    # Scan for fabricated coverage / Available claims (none allowed without LIVE_MAP evidence)
    fabricated_available = 0
    constellation_as_coverage = 0
    fcc_sold_as_live = 0
    coverage_cards = snap.get("coverage") or snap.get("starlink", {}).get("coverage") or []
    if isinstance(coverage_cards, dict):
        coverage_cards = coverage_cards.get("waypoints") or coverage_cards.get("cards") or []
    for card in coverage_cards:
        status = str(card.get("status") or card.get("availability") or "").lower()
        tag = (card.get("tag") or "").upper()
        layer = str(card.get("layer") or "").upper()
        url = card.get("source_url") or card.get("url")
        fetched = card.get("fetched_at")
        evidence = card.get("status_evidence") or card.get("map_status")
        claims_available = "available" in status or status == "works" or card.get("works_there") is True
        if claims_available:
            if tag == "LIVE_MAP" or (tag == "LIVE" and layer in ("L2", "L2_STARLINK_MAP")):
                if not (url and fetched and evidence):
                    fabricated_available += 1
            else:
                fabricated_available += 1
        if claims_available and layer in ("L0", "L0_CONSTELLATION", "CONSTELLATION"):
            constellation_as_coverage += 1
        if claims_available and (
            layer in ("L1", "L1_FCC", "FCC") or tag in ("STALE_SNAPSHOT", "STALE")
        ):
            fcc_sold_as_live += 1

    # Board constellation metrics are CONTEXT for fleet size — not address Available
    # (present as LIVE constellation facts with URLs; must not imply coverage)
    starlink_metrics = snap.get("starlink", {}).get("metrics") or []
    live_constellation = sum(1 for m in starlink_metrics if (m.get("tag") or "").upper() == "LIVE")

    # Millersville home base: UNKNOWN until address map fetch this session
    home = (law.get("family_trip_kits") or {}).get("home_base") or {}
    home_status = home.get("status") or "UNKNOWN"
    md_base_unchecked = 0 if home_status.upper() == "UNKNOWN" else (
        0 if home_status.upper() in ("LIVE_MAP",) and home.get("fetched_at") else 1
    )

    # Default trip claim: HOLD (no green works-there without gates)
    gates = {
        "G1_live_map_or_unknown": {
            "pass": fabricated_available == 0,
            "detail": (
                "No destination LIVE_MAP this session — waypoints UNKNOWN; no fake Available"
                if not coverage_cards
                else f"coverage_cards={len(coverage_cards)} fabricated_available={fabricated_available}"
            ),
        },
        "G2_no_l0_l1_only_available": {
            "pass": constellation_as_coverage == 0 and fcc_sold_as_live == 0,
            "detail": f"constellation_as_coverage={constellation_as_coverage} fcc_sold_as_live={fcc_sold_as_live}",
        },
        "G3_fcc_stale_labeled": {
            "pass": True,
            "detail": "No FCC hex sold as LIVE orderable on this wall",
        },
        "G4_plan_region_match": {
            "pass": True,
            "detail": "Plan tier unread → HOLD (no abroad claim minted)",
        },
        "G5_kit_power_sky": {
            "pass": True,
            "detail": "Family kit schema present as SYNTHETIC logistics; not coverage proof",
        },
        "G6_family_failover": {
            "pass": True,
            "detail": "Failover (cellular/offline) listed in kit minimum — logistics only",
        },
        "G7_america_new_york_stamps": {
            "pass": True,
            "detail": "America/New_York stamps on live_check",
        },
        "G8_synthetic_grey": {
            "pass": True,
            "detail": "Trip kits default SYNTHETIC; constellation metrics stay fleet CONTEXT",
        },
        "G9_never_fabricate_coverage": {
            "pass": fabricated_available == 0,
            "violations": fabricated_available,
            "detail": "No fabricated Available / works-there without LIVE_MAP evidence",
        },
        "G10_no_auto_purchase_plan_rsvp": {
            "pass": True,
            "detail": "auto_purchase=0; coverage-force / availability-claim POST 403",
        },
    }
    failed = [k for k, g in gates.items() if not g.get("pass")]
    # Trip green requires all gates AND at least one LIVE_MAP waypoint — none yet ⇒ HOLD
    trip_claim_green = False
    trip_banner = "HOLD"

    law["live_check"] = {
        "never_fabricate_coverage": 0 if fabricated_available == 0 else fabricated_available,
        "fake_available_claims": fabricated_available,
        "fabricated_coverage_rows": fabricated_available,
        "constellation_as_coverage": constellation_as_coverage,
        "fcc_sold_as_live_capacity": fcc_sold_as_live,
        "md_base_unchecked": md_base_unchecked,
        "home_base": {
            "label": home.get("label") or "Millersville, MD",
            "status": home_status,
            "honesty": home.get("honesty"),
        },
        "trip_claim": trip_banner,
        "trip_claim_green": trip_claim_green,
        "trip_claim_denied": True,
        "failed_gates": failed,
        "gates_passed": len(gates) - len(failed),
        "gates_total": len(gates),
        "gates": gates,
        "live_constellation_metrics": live_constellation,
        "coverage_cards": len(coverage_cards) if isinstance(coverage_cards, list) else 0,
        "public_coverage_maps_only": True,
        "auto_purchase": 0,
        "auto_plan_change": 0,
        "auto_campground_book": 0,
        "auto_announce": 0,
        "coverage_force_succeed": False,
        "fabricate_coverage_succeed": False,
        "availability_claim_succeed": False,
        "fabricate_apis_succeed": False,
        "mutation_endpoints_policy": "403",
        "refused_post_prefixes": list(REFUSED),
        "post_disabled_for_mutations": True,
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
        "snapshot_generated_at": snap.get("generated_at"),
        "disclaimer": (
            "Public coverage maps + family trip kits only. "
            "Not a Starlink reseller. never_fabricate_coverage=0."
        ),
    }
    sc = dict(law.get("scorecard") or {})
    sc["never_fabricate_coverage"] = 0 if fabricated_available == 0 else fabricated_available
    sc["fake_available_claims"] = fabricated_available
    sc["constellation_as_coverage"] = constellation_as_coverage
    sc["fcc_sold_as_live_capacity"] = fcc_sold_as_live
    sc["md_base_unchecked"] = md_base_unchecked
    sc["auto_purchase"] = 0
    sc["burn_outbound"] = 0
    sc["timezone"] = "America/New_York"
    law["scorecard"] = sc
    return law




