def _is125(path):
    return path in REFUSED125 or any(path.startswith(p + "/") for p in REFUSED125)


def brief125_payload() -> dict:
    law = json.loads(BRIEF125.read_text(encoding="utf-8"))
    board = law.get("invent_print_reason_apply_also_refused_by_example") or {}
    ledger = list(board.get("refusals_example") or board.get("ledger") or [])
    for row in ledger:
        if (row.get("status") or "").upper() == "LIVE":
            row["status"] = "EXAMPLE"
        row.setdefault("status", "EXAMPLE")
        row["live_badge"] = False
        if (row.get("honesty") or "").upper() not in ("SYNTHETIC", "EXAMPLE", "EXAMPLE/SYNTHETIC", "SYNTHETIC/EXAMPLE"):
            row["honesty"] = "SYNTHETIC/EXAMPLE"
    paint = dict(board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
    hold["review_private"] = True
    hold["timeout_becomes_refusal"] = False
    hold["cousin_ack"] = {
        "brief_120": False,
        "brief_119": False,
        "brief_091": False,
        "brief_117": False,
        "brief_123": False,
        "brief_121": False,
        "brief_122": False,
        "brief_124": False,
        "brief_116": False,
        "brief_098": False,
        "brief_085": False,
        "brief_088": False,
    }
    fake_live = 1 if (
        paint.get("live_badge") or paint.get("allowed")
        or ((paint.get("status") or "").upper() == "LIVE")
        or (paint.get("refusal_id") is not None)
        or any(r.get("live_badge") or (r.get("status") or "").upper() == "LIVE" for r in ledger)
    ) else 0
    sc = dict(law.get("scorecard") or {})
    sc["merge_apply"] = False
    for k in (
        "invent_refusal_reason", "off_allowlist_reason", "burn_outbound",
        "kit_print_as_invent_print_reason", "dual_digest_live_as_invent_print_reason",
        "snack_also_refused_by_as_invent_print_reason", "fabricate_refusal",
        "fake_live_refusal", "silent_merge_apply", "hold_timeout_refusal",
        "auto_text_kids", "auto_text_print", "auto_text_flight15",
    ):
        sc[k] = 0
    sc["allowlist_reasons_only"] = 1
    sc["review_private_default"] = 1
    if not isinstance(sc.get("also_refused_by"), list):
        sc["also_refused_by"] = ["invent_print_reason_apply", "off_list_print_kit_reason_apply"]
    law["scorecard"] = sc
    cousins = law.get("cousins") or {
        "brief_120": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_119": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply", "kit_print_apply"]},
        "brief_091": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply", "kit_apply"]},
        "brief_117": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply", "dual_digest_live_apply"]},
        "brief_123": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_121": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_122": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_124": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_116": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_098": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_085": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
        "brief_088": {"merge_apply": False, "also_refused_by": ["invent_print_reason_apply"]},
    }
    lc = {
        "ok": True,
        "fake_live": fake_live,
        "fake_live_refusal": 0,
        "fabricate_refusal": 0,
        "invent_refusal_reason": 0,
        "off_allowlist_reason": 0,
        "kit_print_as_invent_print_reason": 0,
        "dual_digest_live_as_invent_print_reason": 0,
        "snack_also_refused_by_as_invent_print_reason": 0,
        "silent_merge_apply": 0,
        "hold_timeout_refusal": 0,
        "allowlist_reasons_only": 1,
        "auto_text_kids": 0,
        "auto_text_flight15": 0,
        "auto_text_print": 0,
        "burn_outbound": 0,
        "merge_apply": False,
        "review_private_default": 1,
        "also_refused_by": list(sc.get("also_refused_by") or ["invent_print_reason_apply"]),
        "ledger": ledger,
        "refusals_example": ledger,
        "live_refusal_paint": paint,
        "notify_hold": hold,
        "refusal_hold": hold,
        "live_refusal": False,
        "live_paint": False,
        "example_only": True,
        "cousins": cousins,
        "family_card": {"state": "HOLD", "recipients_auto": [], "draft_only": True},
        "hold_timeout": {"on_expire": "defer_or_reject", "refusal_paint": None, "text": None},
        "home": "Millersville, MD",
        "place": "Millersville, MD",
        "mutation_endpoints_policy": "403",
        "refused_endpoints": list(REFUSED125),
        "refuse_methods": ["GET", "POST"],
        "pairs": law.get("pairs") or ["brief-120", "brief-119", "brief-091", "brief-117"],
        "pairs_brief120": True,
        "pairs_brief119": True,
        "pairs_brief091": True,
        "pairs_brief117": True,
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
        "honesty_note": (
            "EXAMPLE/SYNTHETIC — kit print / dual-digest LIVE / snack also_refused_by Apply "
            "≠ invent-print-reason or off-list print_kit reason Apply; merge_apply=false; "
            "also_refused_by invent_print_reason_apply; invent_refusal_reason=0; "
            "off_allowlist_reason=0; burn_outbound=0; never auto-text kids/print/Flight15"
        ),
        "briefs_folded_includes_125": True,
    }
    for k in sc:
        if k == "merge_apply":
            lc[k] = False
        elif k == "also_refused_by":
            lc[k] = list(sc[k])
        else:
            lc[k] = sc[k]
    lc["fake_live"] = fake_live
    lc["merge_apply"] = False
    lc["invent_refusal_reason"] = 0
    lc["off_allowlist_reason"] = 0
    lc["kit_print_as_invent_print_reason"] = 0
    lc["dual_digest_live_as_invent_print_reason"] = 0
    lc["snack_also_refused_by_as_invent_print_reason"] = 0
    lc["burn_outbound"] = 0
    law["live_check"] = lc
    return law


