def _is132(path):
    return path in REFUSED132 or any(path.startswith(p + "/") for p in REFUSED132)


def brief132_payload() -> dict:
    law = json.loads(BRIEF132.read_text(encoding="utf-8"))
    board = law.get("print_invent_hold_dual_digest_example") or {}
    digests = list(board.get("digests") or [])
    for d in digests:
        if (d.get("status") or "").upper() == "LIVE":
            d["status"] = "EXAMPLE"
        d.setdefault("status", "EXAMPLE")
        d["live_badge"] = False
        if "SYNTHETIC" not in (d.get("honesty") or "").upper() and "EXAMPLE" not in (d.get("honesty") or "").upper():
            d["honesty"] = "SYNTHETIC"
    proof = dict(board.get("example_proof") or {})
    for key in ("digest_a", "digest_b"):
        dd = dict(proof.get(key) or {})
        if dd:
            if (dd.get("status") or "").upper() == "LIVE":
                dd["status"] = "EXAMPLE"
            dd.setdefault("status", "EXAMPLE")
            dd["live_badge"] = False
            if "SYNTHETIC" not in (dd.get("honesty") or "").upper():
                dd["honesty"] = "SYNTHETIC"
            proof[key] = dd
    proof["live_paint_authorized"] = False
    proof["invent_hold_disposition_eligible"] = False
    if proof.get("match") and "SYNTHETIC" not in (proof.get("honesty") or "").upper():
        proof["honesty"] = "SYNTHETIC — matching digests EXAMPLE only; never invent reason; human Apply still required"
    paint = dict(board.get("live_refusal_row_paint") or board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
    hold["review_private"] = True
    hold["timeout_becomes_refusal"] = False
    hold.setdefault("reason", "awaiting_matching_dual_digests_and_human_apply_for_invent_hold")
    hold["cousin_ack"] = {
        "brief_123": False, "brief_120": False, "brief_121": False, "brief_131": False,
        "brief_130": False, "brief_129": False, "brief_128": False, "brief_127": False,
        "brief_126": False, "brief_125": False, "brief_122": False, "brief_119": False,
    }
    dual_ok = False  # EXAMPLE digests never satisfy LIVE invent-Hold disposition
    fake_live = 1 if (
        paint.get("live_badge") or paint.get("allowed")
        or ((paint.get("status") or "").upper() == "LIVE")
        or (paint.get("refusal_id") is not None)
        or any(d.get("live_badge") or (d.get("status") or "").upper() == "LIVE" for d in digests)
        or proof.get("live_paint_authorized")
        or proof.get("invent_hold_disposition_eligible")
    ) else 0
    sc = dict(law.get("scorecard") or {})
    sc["merge_apply"] = False
    for k in (
        "fabricate_refusal", "fake_live_refusal", "single_digest_live", "mismatch_auto_pick",
        "fabricate_digest", "reuse_stale_digest", "hold_timeout_refusal",
        "invent_refusal_reason",
        "burn_outbound", "auto_text_kids", "auto_text_flight15", "auto_text_print",
        "silent_merge_apply",
    ):
        sc[k] = 0
    sc["dual_proof_required"] = 1
    sc["review_private_default"] = 1
    if not isinstance(sc.get("also_refused_by"), list):
        sc["also_refused_by"] = [
            "invent_hold_dual_digest",
            "invent_hold",
            "single_digest_live",
            "fabricate_refusal",
            "fake_live_refusal",
            "invent_refusal_reason",
        ]
    law["scorecard"] = sc
    cousins = law.get("cousins") or {
        "brief_123": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "invent_hold"]},
        "brief_120": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest"]},
        "brief_121": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "dual_digest_live_apply"]},
        "brief_131": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "print_kit_live_apply"]},
        "brief_130": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest"]},
        "brief_129": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest"]},
        "brief_128": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "live_print_kit_refusal_paint"]},
        "brief_127": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest"]},
        "brief_126": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest"]},
        "brief_125": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "invent_print_reason_apply"]},
        "brief_122": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "print_kit"]},
        "brief_119": {"merge_apply": False, "also_refused_by": ["invent_hold_dual_digest", "kit_print_apply"]},
    }
    pipelines = list(board.get("pipelines_allowlist") or [
        "on_disk_row_sha256", "apply_ledger_row_digest", "cas_store", "git_object_id",
    ])
    lc = {
        "ok": True,
        "fake_live": fake_live,
        "fake_live_refusal": 0,
        "fabricate_refusal": 0,
        "invent_refusal_reason": 0,
        "single_digest_live": 0,
        "dual_proof_required": 1,
        "dual_proof": dual_ok,
        "mismatch_auto_pick": 0,
        "fabricate_digest": 0,
        "reuse_stale_digest": 0,
        "hold_timeout_refusal": 0,
        "auto_text_kids": 0,
        "auto_text_flight15": 0,
        "auto_text_print": 0,
        "burn_outbound": 0,
        "merge_apply": False,
        "silent_merge_apply": 0,
        "review_private_default": 1,
        "also_refused_by": list(sc.get("also_refused_by") or ["invent_hold_dual_digest"]),
        "pipelines_allowlist": pipelines,
        "digests": digests,
        "example_proof": proof,
        "live_refusal_row_paint": paint,
        "live_refusal_paint": paint,
        "notify_hold": hold,
        "refusal_hold": hold,
        "live_refusal": False,
        "live_paint": False,
        "example_only": True,
        "cousins": cousins,
        "family_card": {"state": "HOLD", "recipients_auto": [], "draft_only": True},
        "hold_timeout": {"on_expire": "defer_or_reject", "refusal_paint": None, "text": None},
        "home": "Millersville, MD",
        "place": "Millersville, MD",
        "mutation_endpoints_policy": "403",
        "refused_endpoints": list(REFUSED132),
        "refuse_methods": ["GET", "POST"],
        "pairs": law.get("pairs") or ["brief-123", "brief-120", "brief-121"],
        "pairs_brief123": True,
        "pairs_brief120": True,
        "pairs_brief121": True,
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
        "honesty_note": (
            "EXAMPLE/SYNTHETIC — invent-Hold dual ledger digests EXAMPLE only; "
            "never invent-Hold disposition / cyan LIVE without this-session dual independent digests + Hold→Apply; "
            "never invent reason codes; invent_refusal_reason=0; fabricate_refusal=0; dual_proof_required=1; "
            "fake_live_refusal=0; single_digest_live=0; merge_apply=false; also_refused_by invent_hold_dual_digest; "
            "burn_outbound=0; never auto-text kids/print/Flight15"
        ),
        "briefs_folded_includes_132": True,
    }
    for k in sc:
        if k == "merge_apply":
            lc[k] = False
        elif k == "also_refused_by":
            lc[k] = list(sc[k])
        else:
            lc[k] = sc[k]
    lc["fake_live"] = fake_live
    lc["dual_proof_required"] = 1
    lc["dual_proof"] = dual_ok
    lc["merge_apply"] = False
    lc["fabricate_refusal"] = 0
    lc["fake_live_refusal"] = 0
    lc["single_digest_live"] = 0
    lc["invent_refusal_reason"] = 0
    lc["burn_outbound"] = 0
    lc["hold_timeout_refusal"] = 0
    lc["silent_merge_apply"] = 0
    lc["mismatch_auto_pick"] = 0
    lc["fabricate_digest"] = 0
    lc["reuse_stale_digest"] = 0
    law["live_check"] = lc
    return law





