def brief140_payload() -> dict:
    law = json.loads(BRIEF140.read_text(encoding="utf-8"))
    board = law.get("invent_hold_offlist_live_as_invent_print_reason_also_refused_by_example") or {}
    digests = list(board.get("digests") or [])
    for d in digests:
        if (d.get("status") or "").upper() == "LIVE":
            d["status"] = "EXAMPLE"
        d.setdefault("status", "EXAMPLE")
        d["live_badge"] = False
        if "SYNTHETIC" not in (d.get("honesty") or "").upper() and "EXAMPLE" not in (d.get("honesty") or "").upper():
            d["honesty"] = "SYNTHETIC"
    proof = dict(board.get("example_proof") or {})
    for key in ("digest_a", "digest_b"):
        dd = dict(proof.get(key) or {})
        if dd:
            if (dd.get("status") or "").upper() == "LIVE":
                dd["status"] = "EXAMPLE"
            dd.setdefault("status", "EXAMPLE")
            dd["live_badge"] = False
            if "SYNTHETIC" not in (dd.get("honesty") or "").upper():
                dd["honesty"] = "SYNTHETIC"
            proof[key] = dd
    proof["live_paint_authorized"] = False
    proof["invent_live_eligible"] = False
    if proof.get("match") and "SYNTHETIC" not in (proof.get("honesty") or "").upper():
        proof["honesty"] = "SYNTHETIC — invent-Hold / off-list dual-digest LIVE paint ≠ invent-print-reason Apply; human Apply still required"
    paint = dict(board.get("live_refusal_row_paint") or board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold["auto_mint"] = None
    hold["auto_live"] = None
    hold["auto_pick"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
    hold["review_private"] = True
    hold["timeout_becomes_refusal"] = False
    hold["timeout_becomes_live"] = False
    hold["timeout_becomes_auto_pick"] = False
    hold.setdefault("reason", "awaiting_human_apply_for_invent_print_reason_not_invent_hold_offlist_alone")
    hold["cousin_ack"] = {
        "brief_125": False, "brief_123": False, "brief_124": False, "brief_120": False,
        "brief_139": False, "brief_138": False, "brief_137": False, "brief_136": False,
        "brief_135": False, "brief_134": False, "brief_133": False, "brief_132": False,
        "brief_131": False, "brief_130": False, "brief_129": False, "brief_128": False,
        "brief_127": False, "brief_126": False, "brief_122": False, "brief_121": False, "brief_119": False,
    }
    dual_ok = False  # EXAMPLE digests never satisfy LIVE invent-print-reason Apply paint
    fake_live = 1 if (
        paint.get("live_badge") or paint.get("allowed")
        or ((paint.get("status") or "").upper() == "LIVE")
        or (paint.get("refusal_id") is not None)
        or any(d.get("live_badge") or (d.get("status") or "").upper() == "LIVE" for d in digests)
        or proof.get("live_paint_authorized")
        or proof.get("invent_live_eligible")
    ) else 0
    sc = dict(law.get("scorecard") or {})
