def _is164(path):
    return path in REFUSED164 or any(path.startswith(p + "/") for p in REFUSED164)


def brief164_payload() -> dict:
    law = json.loads(BRIEF164.read_text(encoding="utf-8"))
    board = dict(law.get("live_print_kit_refusal_paint_cas_review_private_before_route_to_allowlist_extension_apply_example") or {})
    reject_row = dict(board.get("example_membership_reject_apply") or {})
    route_row = dict(board.get("example_membership_route_apply") or {})
    mismatch_row = dict(board.get("example_membership_mismatch_refused") or {})
    extension_proof_row = dict(board.get("example_extension_membership_proof") or {})
    for row in (reject_row, route_row, mismatch_row, extension_proof_row):
        if not row:
            continue
        if (row.get("status") or "").upper() == "LIVE":
            row["status"] = "EXAMPLE"
        row.setdefault("status", "EXAMPLE")
        row["live_badge"] = False
        row["live_paint_authorized"] = False
        row["invented"] = False
        if "SYNTHETIC" not in (row.get("honesty") or "").upper() and "EXAMPLE" not in (row.get("honesty") or "").upper():
            row["honesty"] = "SYNTHETIC/EXAMPLE"
        if row.get("apply_surface") and row.get("apply_surface") not in (
            "reject_apply", "route_to_allowlist_extension_apply",
        ):
            row["apply_surface"] = "reject_apply"
        for dig_key in ("membership_digest_a", "membership_digest_b"):
            dig = dict(row.get(dig_key) or {})
            if dig:
                if (dig.get("status") or "").upper() == "LIVE":
                    dig["status"] = "EXAMPLE"
                dig.setdefault("status", "EXAMPLE")
                dig["live_badge"] = False
                row[dig_key] = dig
    if mismatch_row:
        mismatch_row["digests_match"] = False
        mismatch_row["apply_closed"] = False
    paint = dict(board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold["auto_mint"] = None
    hold["auto_live"] = None
    hold["auto_pick"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
    hold["review_private"] = True
    hold["cas_required"] = True
    hold["membership_proof_required"] = True
    hold["timeout_becomes_refusal"] = False
    hold["timeout_becomes_live"] = False
    hold["timeout_becomes_auto_mint"] = False
