def _is151(path):
    return path in REFUSED151 or any(path.startswith(p + "/") for p in REFUSED151)


def brief151_payload() -> dict:
    law = json.loads(BRIEF151.read_text(encoding="utf-8"))
    board = law.get("live_print_kit_refusal_paint_off_list_disposition_cas_review_private_gate_example") or {}
    reject_row = dict(board.get("example_cas_reject_apply") or {})
    route_row = dict(board.get("example_cas_route_apply") or {})
    lost_row = dict(board.get("example_cas_lost_update_refused") or {})
    for row in (reject_row, route_row, lost_row):
        if not row:
            continue
        if (row.get("status") or "").upper() == "LIVE":
            row["status"] = "EXAMPLE"
        row.setdefault("status", "EXAMPLE")
        row["live_badge"] = False
        row["live_paint_authorized"] = False
        row["invented"] = False
        if "SYNTHETIC" not in (row.get("honesty") or "").upper() and "EXAMPLE" not in (row.get("honesty") or "").upper():
            row["honesty"] = "SYNTHETIC/EXAMPLE"
        if row.get("apply_surface") and row.get("apply_surface") not in (
            "reject_apply", "route_to_allowlist_extension_apply",
        ):
            row["apply_surface"] = "reject_apply"
        cas = dict(row.get("cas") or {})
        if cas:
            row["cas"] = cas
    if lost_row:
        lost_row["apply_closed"] = False
        if (lost_row.get("cas") or {}).get("result") != "conflict":
            lost_row.setdefault("cas", {})["result"] = "conflict"
    paint = dict(board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold["auto_mint"] = None
    hold["auto_live"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
