def _is146(path):
    return path in REFUSED146 or any(path.startswith(p + "/") for p in REFUSED146)


def brief146_payload() -> dict:
    law = json.loads(BRIEF146.read_text(encoding="utf-8"))
    board = law.get("mismatch_auto_pick_or_fabricate_also_refused_by_example") or {}
    attempt_row = dict(board.get("example_trigger_attempt") or {})
    fab_row = dict(board.get("example_fabricate_attempt") or {})
    for row in (attempt_row, fab_row):
        if not row:
            continue
        if (row.get("status") or "").upper() == "LIVE":
            row["status"] = "EXAMPLE"
        row.setdefault("status", "EXAMPLE")
        row["live_badge"] = False
        row["live_paint_authorized"] = False
        row["cyan_live"] = False
        row["auto_pick"] = False
        row["fabricate_live_refusal"] = False
        if "SYNTHETIC" not in (row.get("honesty") or "").upper() and "EXAMPLE" not in (row.get("honesty") or "").upper():
            row["honesty"] = "SYNTHETIC/EXAMPLE"
    attempt_row["attempt_ok"] = False
    attempt_row["invented"] = False
    paint = dict(board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold["auto_pick"] = None
    hold["auto_live"] = None
    hold.setdefault("default", "review_private")
