def _is145(path):
    return path in REFUSED145 or any(path.startswith(p + "/") for p in REFUSED145)


def brief145_payload() -> dict:
    law = json.loads(BRIEF145.read_text(encoding="utf-8"))
    board = law.get("named_mismatch_hold_apply_surface_allowlist_example") or {}
    attempt_row = dict(board.get("example_surface_attempt") or {})
    off_row = dict(board.get("example_off_list_surface") or {})
    for row in (attempt_row, off_row):
        if not row:
            continue
        if (row.get("status") or "").upper() == "LIVE":
            row["status"] = "EXAMPLE"
        row.setdefault("status", "EXAMPLE")
        row["live_badge"] = False
        row["live_paint_authorized"] = False
        row["cyan_live"] = False
        row["auto_pick"] = False
        if "SYNTHETIC" not in (row.get("honesty") or "").upper() and "EXAMPLE" not in (row.get("honesty") or "").upper():
            row["honesty"] = "SYNTHETIC/EXAMPLE"
    attempt_row["apply_satisfied"] = False
    attempt_row["invented"] = False
    paint = dict(board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold["auto_pick"] = None
    hold["auto_live"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
    hold["review_private"] = True
    hold["timeout_becomes_refusal"] = False
    hold["timeout_becomes_live"] = False
    hold.setdefault("reason", "mismatch_hold_apply")
    hold["cousin_ack"] = {
        "brief_127": False, "brief_121": False, "brief_144": False, "brief_143": False,
        "brief_142": False, "brief_141": False, "brief_140": False, "brief_139": False,
        "brief_138": False, "brief_137": False, "brief_136": False, "brief_135": False,
        "brief_134": False, "brief_133": False, "brief_132": False, "brief_131": False,
        "brief_130": False, "brief_129": False, "brief_128": False, "brief_126": False,
        "brief_125": False, "brief_124": False, "brief_123": False, "brief_122": False,
        "brief_120": False, "brief_119": False, "brief_117": False, "brief_116": False,
        "brief_098": False, "brief_091": False, "brief_085": False, "brief_088": False,
    }
    fake_live = 1 if (
        paint.get("live_badge") or paint.get("allowed")
        or ((paint.get("status") or "").upper() == "LIVE")
        or (paint.get("refusal_id") is not None)
        or attempt_row.get("live_badge") or attempt_row.get("live_paint_authorized") or attempt_row.get("cyan_live")
        or off_row.get("live_badge") or off_row.get("live_paint_authorized") or off_row.get("cyan_live")
        or ((attempt_row.get("status") or "").upper() == "LIVE")
        or ((off_row.get("status") or "").upper() == "LIVE")
        or attempt_row.get("apply_satisfied")
        or attempt_row.get("auto_pick")
    ) else 0
    sc = dict(law.get("scorecard") or {})
    sc["merge_apply"] = False
    for k in (
        "invent_apply_surface", "invent_pipeline", "off_allowlist_pipeline",
        "mismatch_auto_pick", "fabricate_refusal", "hold_timeout_refusal",
        "fake_live_refusal", "fabricate_digest", "single_digest_live", "reuse_stale_digest",
        "burn_outbound", "auto_text_kids", "auto_text_print", "auto_text_flight15",
        "silent_merge_apply",
    ):
        sc[k] = 0
    sc["dual_proof_required"] = 1
    sc["review_private_default"] = 1
    sc["allowlist_apply_surfaces_only"] = 1
    sc["allowlist_pipelines_only"] = 1
    if not isinstance(sc.get("also_refused_by"), list):
        sc["also_refused_by"] = [
            "mismatch_hold_apply",
            "invent_apply_surface",
            "allowlist_apply_surfaces_only",
            "mismatch_auto_pick",
            "fabricate_refusal",
            "fake_live_refusal",
            "hold_timeout_refusal",
            "dual_proof_required",
        ]
    law["scorecard"] = sc
    cousins = law.get("cousins") or {}
    for ck, cv in list(cousins.items()):
        if isinstance(cv, dict):
            cv["merge_apply"] = False
    surfaces = list(board.get("allowlisted_apply_surfaces") or [
        "mismatch_hold_reject_apply",
        "mismatch_hold_refetch_digests_apply",
        "mismatch_hold_attach_matching_digest_apply",
    ])
    lc = {
        "ok": True,
        "example_surface_attempt": attempt_row,
        "example_off_list_surface": off_row,
        "live_refusal_paint": paint,
        "refusal_hold": hold,
        "notify_hold": hold,
        "allowlisted_apply_surfaces": surfaces,
        "cousins": cousins,
        "mutation_endpoints_policy": "403",
        "refused_endpoints": list(REFUSED145),
        "refuse_methods": ["GET", "POST"],
        "pairs": law.get("pairs") or ["brief-127", "brief-121"],
        "pairs_brief127": True,
        "pairs_brief121": True,
        "cousins_brief144": True,
        "cousins_brief143": True,
        "cousins_brief142": True,
        "cousins_brief141": True,
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
        "honesty_note": (
            "EXAMPLE/SYNTHETIC — only mismatch_hold_reject_apply / mismatch_hold_refetch_digests_apply / "
            "mismatch_hold_attach_matching_digest_apply may attempt disposition Apply; "
            "still merge_apply=false / also_refused_by mismatch_hold_apply; never invent surface; "
            "never cyan LIVE from membership; invent_apply_surface=0; allowlist_apply_surfaces_only=1; "
            "invent_pipeline=0; off_allowlist_pipeline=0; allowlist_pipelines_only=1; "
            "mismatch_auto_pick=0; fabricate_refusal=0; hold_timeout_refusal=0; dual_proof_required=1; "
            "burn_outbound=0; never auto-text kids/print/Flight15"
        ),
        "dual_proof": False,
        "briefs_folded_includes_145": True,
        "prefer_note": (
            "Prefer 145 on mismatch-Hold Apply surface allow-list paths; keep unique prior ownership "
            "(144 disposition board, 143 live_print_kit_pipeline_paint, 142 off-list disposition, "
            "141 pipeline-aware mismatch Hold, 127 mismatch Hold open, 121 dual-digest match)."
        ),
    }
    for k in sc:
        if k == "merge_apply":
            lc[k] = False
        elif k == "also_refused_by":
            lc[k] = list(sc[k])
        else:
            lc[k] = sc[k]
    lc["fake_live"] = fake_live
    lc["merge_apply"] = False
    lc["invent_apply_surface"] = 0
    lc["allowlist_apply_surfaces_only"] = 1
    lc["invent_pipeline"] = 0
    lc["off_allowlist_pipeline"] = 0
    lc["allowlist_pipelines_only"] = 1
    lc["mismatch_auto_pick"] = 0
    lc["fabricate_refusal"] = 0
    lc["hold_timeout_refusal"] = 0
    lc["dual_proof_required"] = 1
    lc["fake_live_refusal"] = 0
    lc["fabricate_digest"] = 0
    lc["single_digest_live"] = 0
    lc["reuse_stale_digest"] = 0
    lc["burn_outbound"] = 0
    lc["silent_merge_apply"] = 0
    lc["review_private_default"] = 1
    law["live_check"] = lc
    return law


