def _is142(path):
    return path in REFUSED142 or any(path.startswith(p + "/") for p in REFUSED142)


def brief142_payload() -> dict:
    law = json.loads(BRIEF142.read_text(encoding="utf-8"))
    board = law.get("named_off_list_digest_pipeline_disposition_board_example") or {}
    reject_row = dict(board.get("example_off_list_disposition") or {})
    route_row = dict(board.get("example_route_to_extension") or {})
    for row in (reject_row, route_row):
        if not row:
            continue
        if (row.get("status") or "").upper() == "LIVE":
            row["status"] = "EXAMPLE"
        row.setdefault("status", "EXAMPLE")
        row["live_badge"] = False
        row["live_paint_authorized"] = False
        row["invented"] = False
        if "SYNTHETIC" not in (row.get("honesty") or "").upper() and "EXAMPLE" not in (row.get("honesty") or "").upper():
            row["honesty"] = "SYNTHETIC/EXAMPLE"
    paint = dict(board.get("live_refusal_paint") or {})
    paint["allowed"] = False
    paint["live_badge"] = False
    paint["refusal_id"] = None
    if (paint.get("status") or "").upper() == "LIVE":
        paint["status"] = "EXAMPLE"
    paint.setdefault("status", "EXAMPLE")
    hold = dict(board.get("hold") or {})
    hold.setdefault("state", "HOLD")
    hold["destination"] = None
    hold["auto_paint"] = None
    hold["auto_text"] = None
    hold["auto_mint"] = None
    hold["auto_live"] = None
    hold.setdefault("default", "review_private")
    hold.setdefault("options", list(law.get("notify_hold_destinations") or []))
    hold["review_private"] = True
    hold["timeout_becomes_refusal"] = False
    hold["timeout_becomes_live"] = False
    hold["timeout_becomes_auto_mint"] = False
    hold.setdefault("reason", "off_list_digest_pipeline_disposition")
    hold["cousin_ack"] = {
        "brief_126": False, "brief_121": False, "brief_141": False, "brief_140": False,
        "brief_139": False, "brief_138": False, "brief_137": False, "brief_136": False,
        "brief_135": False, "brief_134": False, "brief_133": False, "brief_132": False,
        "brief_131": False, "brief_130": False, "brief_129": False, "brief_128": False,
        "brief_127": False, "brief_125": False, "brief_124": False, "brief_123": False,
        "brief_122": False, "brief_120": False, "brief_119": False, "brief_117": False,
        "brief_116": False, "brief_098": False, "brief_091": False, "brief_085": False,
        "brief_088": False,
    }
    fake_live = 1 if (
        paint.get("live_badge") or paint.get("allowed")
        or ((paint.get("status") or "").upper() == "LIVE")
        or (paint.get("refusal_id") is not None)
        or reject_row.get("live_badge") or reject_row.get("live_paint_authorized")
        or route_row.get("live_badge") or route_row.get("live_paint_authorized")
        or ((reject_row.get("status") or "").upper() == "LIVE")
        or ((route_row.get("status") or "").upper() == "LIVE")
        or reject_row.get("invented")
    ) else 0
    sc = dict(law.get("scorecard") or {})
    sc["merge_apply"] = False
    for k in (
        "invent_pipeline", "off_allowlist_pipeline", "fabricate_refusal", "hold_timeout_refusal",
        "fake_live_refusal", "fabricate_digest", "single_digest_live", "reuse_stale_digest",
        "burn_outbound", "auto_text_kids", "auto_text_print", "auto_text_flight15",
        "silent_merge_apply",
    ):
        sc[k] = 0
    sc["dual_proof_required"] = 1
    sc["review_private_default"] = 1
    sc["allowlist_pipelines_only"] = 1
    if not isinstance(sc.get("also_refused_by"), list):
        sc["also_refused_by"] = [
            "named_off_list_digest_pipeline_disposition",
            "invent_pipeline",
            "off_allowlist_pipeline",
            "allowlist_pipelines_only",
            "fabricate_refusal",
            "fake_live_refusal",
            "hold_timeout_refusal",
        ]
    law["scorecard"] = sc
    cousins = law.get("cousins") or {}
    for ck, cv in list(cousins.items()):
        if isinstance(cv, dict):
            cv["merge_apply"] = False
    pipelines = list(board.get("allow_list") or [
        "on_disk_row_sha256", "apply_ledger_row_digest", "cas_store", "git_object_id",
    ])
    lc = {
        "ok": True,
        "example_off_list_disposition": reject_row,
        "example_route_to_extension": route_row,
        "live_refusal_paint": paint,
        "refusal_hold": hold,
        "notify_hold": hold,
        "allow_list": pipelines,
        "cousins": cousins,
        "mutation_endpoints_policy": "403",
        "refused_endpoints": list(REFUSED142),
        "refuse_methods": ["GET", "POST"],
        "pairs": law.get("pairs") or ["brief-126", "brief-121"],
        "pairs_brief126": True,
        "pairs_brief121": True,
        "cousins_brief141": True,
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
        "honesty_note": (
            "EXAMPLE/SYNTHETIC — proposed digest pipeline ∉ allow-list ⇒ disposition reject / "
            "route-to-allowlist-extension only; never cyan LIVE; never invent pipeline; "
            "invent_pipeline=0; off_allowlist_pipeline=0; allowlist_pipelines_only=1; "
            "fabricate_refusal=0; dual_proof_required=1; hold_timeout_refusal=0; "
            "merge_apply=false; also_refused_by named_off_list_digest_pipeline_disposition; "
            "burn_outbound=0; never auto-text kids/print/Flight15"
        ),
        "dual_proof": False,
        "briefs_folded_includes_142": True,
        "prefer_note": (
            "Prefer 142 on off-list disposition paths with also_refused_by overlaps; keep unique prior ownership "
            "(126 allow-list membership, 121 dual-digest match, 141 pipeline-aware mismatch Hold, "
            "135 off-list digest-pipeline rail, 136 off-list mismatch Hold, 137 LIVE off-list paint)."
        ),
    }
    for k in sc:
        if k == "merge_apply":
            lc[k] = False
        elif k == "also_refused_by":
            lc[k] = list(sc[k])
        else:
            lc[k] = sc[k]
    lc["fake_live"] = fake_live
    lc["merge_apply"] = False
    lc["invent_pipeline"] = 0
    lc["off_allowlist_pipeline"] = 0
    lc["allowlist_pipelines_only"] = 1
    lc["fabricate_refusal"] = 0
    lc["hold_timeout_refusal"] = 0
    lc["dual_proof_required"] = 1
    lc["fake_live_refusal"] = 0
    lc["fabricate_digest"] = 0
    lc["single_digest_live"] = 0
    lc["reuse_stale_digest"] = 0
    lc["burn_outbound"] = 0
    lc["silent_merge_apply"] = 0
    lc["review_private_default"] = 1
    law["live_check"] = lc
    return law


