def _refuse049(path, method):
    return {"ok": False, "error": "refused", "brief_id": "brief-049", "method": method, "path": path,
            "message": ("Starship launch window family alert law (brief-049). Never fabricate LIVE telemetry/T-0, "
                        "never auto-text/notify kids, never auto-book trip, never auto-post launch, never force READY. "
                        "fabricate_telemetry=0; auto_text_launch=0; America/New_York. Not KPD.")}


def _is049(path):
    return path in REFUSED049 or any(path.startswith(p + "/") for p in REFUSED049)


def brief049_payload() -> dict:
    law = json.loads(BRIEF049.read_text(encoding="utf-8"))
    b26 = brief026_payload()["live_check"]
    snap = load_snapshot() if SNAPSHOT.is_file() else {}
    windows = []
    for L in snap.get("launches", []):
        name = (L.get("name") or L.get("id") or "")
        if "starship" not in (name + str(L.get("id"))).lower():
            continue
        tag = (L.get("tag") or "UNKNOWN").upper()
        proven = tag == "LIVE" and bool(L.get("source_url")) and bool(L.get("fetched_at"))
        status = (L.get("status") or "")
        unofficial = "unofficial" in status.lower() or "not announced" in (L.get("note") or "").lower()
        windows.append({"id": L.get("id"), "name": name, "tag": tag, "status": status,
                        "net_label": "NET_UNOFFICIAL" if unofficial else ("PROVEN" if proven else "window_unknown"),
                        "ticking_t0": False if (unofficial or not proven) else b26.get("hero_official_clock_enabled", False),
                        "source_url": L.get("source_url"), "fetched_at": L.get("fetched_at")})
    fake_t0 = sum(1 for w in windows if w["ticking_t0"] and w["net_label"] != "PROVEN")
    law["live_check"] = {
        "fabricate_telemetry": b26.get("fabricate_telemetry", 0),
        "fabricate_t0": fake_t0,
        "auto_text_launch": 0, "auto_notify_kids": 0, "auto_book_trip": 0,
        "auto_post_launch": 0, "mission_ready_force": 0, "burn_outbound": 0,
        "window_board": windows,
        "family_alert": {"state": "HOLD", "recipients_auto": [], "requires": "Boyd/Miranda Apply",
                         "draft_only": True},
        "trip": {"banner": "HOLD", "auto_book": 0},
        "mission_ready": b26.get("mission_ready"),
        "mission_ready_banner": b26.get("mission_ready_banner"),
        "hero_official_clock_enabled": b26.get("hero_official_clock_enabled"),
        "home": "Millersville, MD",
        "mutation_endpoints_policy": "403",
        "refused_endpoints": list(REFUSED049),
        "refuse_methods": ["GET", "POST"],
        "pairs": ["brief-026", "brief-019", "brief-020"],
        "timezone": "America/New_York",
        "served_at_et": _stamp(),
    }
    sc = dict(law.get("scorecard") or {})
    sc["fabricate_telemetry"] = law["live_check"]["fabricate_telemetry"]
    sc["fabricate_t0"] = fake_t0
    law["scorecard"] = sc
    return law


